const query = ($('On GIF Search').item.json.query || '').trim();
const resp = $('Search GIPHY').item.json || {};
const gifs = Array.isArray(resp.data) ? resp.data : [];

let cards = '';
for (const g of gifs) {
  const img = g && g.images && g.images.fixed_height && g.images.fixed_height.url;
  if (!img) continue;
  const alt = (g.title || 'GIF').replace(/"/g, '&quot;');
  cards += `<div class="gifcard" data-url="${img}" style="flex:1 1 30%;min-width:140px;position:relative;cursor:pointer;"><img src="${img}" alt="${alt}" style="width:100%;border-radius:12px;display:block;"/><span class="badge" style="position:absolute;bottom:8px;left:8px;background:rgba(0,0,0,0.72);color:#fff;font-size:12px;padding:3px 8px;border-radius:8px;">Click to copy</span></div>`;
}

if (!cards) {
  cards = '<p style="text-align:center;color:#6b7280;">No GIFs found — try another search 🙈</p>';
}

const html = `
<div style="max-width:760px;margin:0 auto;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#1f2937;">
  <h1 style="text-align:center;font-size:28px;margin-bottom:4px;">🎬 Top GIFs for "${query}"</h1>
  <p style="text-align:center;color:#6b7280;margin-top:0;">Tap any GIF to copy its link — then paste it anywhere 👇</p>
  <div style="display:flex;flex-wrap:wrap;gap:12px;margin-top:18px;">${cards}</div>
  <p style="text-align:center;color:#9ca3af;font-size:13px;margin-top:24px;">Powered by GIPHY · Refresh the form to search again 🔄</p>
</div>
<script>
(function(){
  function attach(){
    var cards = document.querySelectorAll('.gifcard');
    for (var i = 0; i < cards.length; i++) {
      (function(el){
        el.addEventListener('click', function(){
          var url = el.getAttribute('data-url');
          var badge = el.querySelector('.badge');
          function ok(){ if(badge){ badge.textContent = '✅ Copied!'; setTimeout(function(){ badge.textContent = 'Click to copy'; }, 1200); } }
          function fail(){ if(badge){ badge.textContent = '⚠️ Copy failed'; setTimeout(function(){ badge.textContent = 'Click to copy'; }, 1200); } }
          if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(url).then(ok).catch(fail);
          } else {
            var ta = document.createElement('textarea');
            ta.value = url; document.body.appendChild(ta); ta.select();
            try { document.execCommand('copy'); ok(); } catch(e){ fail(); }
            document.body.removeChild(ta);
          }
        });
      })(cards[i]);
    }
  }
  if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', attach); } else { attach(); }
})();
</script>
`;

return [{ json: { html } }];
